// RestoreURL builds the /restore endpoint URL carrying a deleted todo's fields
// as query params (url-encoded), so the server can reconstruct it with no
// server-side memory. Used as the "Undo" action on the delete toast.
func RestoreURL(t todo.Todo) string {
	return fmt.Sprintf(
		"/api/examples/todo/restore?id=%d&title=%s&done=%t&priority=%s&due=%s&order=%d",
		t.ID,
		url.QueryEscape(t.Title),
		t.Done,
		url.QueryEscape(t.Priority),
		url.QueryEscape(t.Due),
		t.Order,
	)
}

